/* 016_AckDashboard_Create.sql - pending acknowledgement query used by AckDashboardService. */
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO
CREATE OR ALTER PROCEDURE dbo.Ack_GetPending
	@VesselID int = NULL,
	@UserID varchar(50) = NULL,
	@Office bit = 0
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @dm int = ISNULL(TRY_CAST((SELECT TOP (1) SettingValue FROM dbo.DM_Settings WHERE SettingName = 'DefaultAckDueDays') AS int), 7);
	DECLARE @dc int = ISNULL(TRY_CAST((SELECT TOP (1) SettingValue FROM dbo.CIR_Settings WHERE SettingName = 'DefaultAckDueDays_Circular') AS int), 7);
	DECLARE @da int = ISNULL(TRY_CAST((SELECT TOP (1) SettingValue FROM dbo.CIR_Settings WHERE SettingName = 'DefaultAckDueDays_Alert') AS int), 1);
	IF @Office = 1
	BEGIN
		WITH mv AS (SELECT v.DM_ManualID, v.DM_ManualVersionID, v.Version, COALESCE(v.ReleasedDate, v.PublishedDate, v.CreatedDate) AS ReleasedOn, ROW_NUMBER() OVER (PARTITION BY v.DM_ManualID ORDER BY v.DM_ManualVersionID DESC) AS rn FROM dbo.DM_ManualVersion v WHERE v.IsActive = 1), man AS (SELECT m.DM_ManualID, m.ManualNo, m.ManualName, ISNULL(m.AckDueDays, @dm) AS AckDueDays, mv.DM_ManualVersionID, mv.Version, mv.ReleasedOn FROM dbo.DM_Manual m JOIN mv ON mv.DM_ManualID = m.DM_ManualID AND mv.rn = 1 WHERE ISNULL(m.IsDeleted, 0) <> 1), cir AS (SELECT c.CIR_MasterID, c.CIR_Number, c.Title, CASE WHEN c.CircularType LIKE 'Alert%' THEN 'Alert' ELSE 'Circular' END AS ItemType, COALESCE(c.ReleasedDate, c.DateIssued, c.CreatedDate) AS ReleasedOn, ISNULL(c.AckDueDays, CASE WHEN c.CircularType LIKE 'Alert%' THEN @da ELSE @dc END) AS AckDueDays FROM dbo.CIR_Master c WHERE ISNULL(c.IsDeleted, 0) <> 1 AND ISNULL(c.Status, '') NOT IN ('Temp', 'Draft', 'Cancelled') AND (c.ValidUntil IS NULL OR c.ValidUntil >= CAST(GETDATE() AS date)))
		SELECT -1 AS VesselID, 'Office' AS VesselName, 'Manual' AS ItemType, man.DM_ManualID AS ItemID, man.ManualNo AS Number, man.ManualName AS Title, man.Version, u.Role AS Rank, u.UserID, u.UserName, u.HQDept AS Dept, man.ReleasedOn, DATEADD(day, man.AckDueDays, man.ReleasedOn) AS DueOn, man.AckDueDays FROM dbo.DM_Manual_ToAck_HQ t JOIN dbo.HQ_Users u ON u.HQ_UsersID = t.HQ_UsersID AND ISNULL(u.IsDisabled, 0) = 0 JOIN man ON man.DM_ManualID = t.DM_ManualID WHERE ISNULL(t.IsActive, 1) = 1 AND (@UserID IS NULL OR u.UserID = @UserID) AND NOT EXISTS (SELECT 1 FROM dbo.DM_Manual_UserAck a WHERE a.DM_ManualVersionID = man.DM_ManualVersionID AND a.UserID = u.UserID)
		UNION ALL
		SELECT -1, 'Office', cir.ItemType, cir.CIR_MasterID, cir.CIR_Number, cir.Title, NULL, u.Role, u.UserID, u.UserName, u.HQDept, cir.ReleasedOn, DATEADD(day, cir.AckDueDays, cir.ReleasedOn), cir.AckDueDays FROM dbo.CIR_ToAck_HQ t JOIN dbo.HQ_Users u ON u.HQ_UsersID = t.HQ_UsersID AND ISNULL(u.IsDisabled, 0) = 0 JOIN cir ON cir.CIR_MasterID = t.CIR_MasterID WHERE ISNULL(t.IsActive, 1) = 1 AND (@UserID IS NULL OR u.UserID = @UserID) AND NOT EXISTS (SELECT 1 FROM dbo.CIR_UserAck a WHERE a.CIR_MasterID = cir.CIR_MasterID AND a.VesselID = -1 AND a.Fleet_CrewID = u.HQ_UsersID);
		RETURN;
	END;
	WITH vessels AS (SELECT VesselID, VslName FROM dbo.V_Vessel WHERE VesselID > 0 AND ISNULL(IsRetired, 0) = 0 AND (@VesselID IS NULL OR VesselID = @VesselID)), mv AS (SELECT v.DM_ManualID, v.DM_ManualVersionID, v.Version, COALESCE(v.ReleasedDate, v.PublishedDate, v.CreatedDate) AS ReleasedOn, ROW_NUMBER() OVER (PARTITION BY v.DM_ManualID ORDER BY v.DM_ManualVersionID DESC) AS rn FROM dbo.DM_ManualVersion v WHERE v.IsActive = 1), man AS (SELECT m.DM_ManualID, m.ManualNo, m.ManualName, ISNULL(m.AckDueDays, @dm) AS AckDueDays, mv.DM_ManualVersionID, mv.Version, mv.ReleasedOn FROM dbo.DM_Manual m JOIN mv ON mv.DM_ManualID = m.DM_ManualID AND mv.rn = 1 WHERE ISNULL(m.IsDeleted, 0) <> 1), cir AS (SELECT c.CIR_MasterID, c.CIR_Number, c.Title, CASE WHEN c.CircularType LIKE 'Alert%' THEN 'Alert' ELSE 'Circular' END AS ItemType, COALESCE(c.ReleasedDate, c.DateIssued, c.CreatedDate) AS ReleasedOn, ISNULL(c.AckDueDays, CASE WHEN c.CircularType LIKE 'Alert%' THEN @da ELSE @dc END) AS AckDueDays FROM dbo.CIR_Master c WHERE ISNULL(c.IsDeleted, 0) <> 1 AND ISNULL(c.Status, '') NOT IN ('Temp', 'Draft', 'Cancelled') AND (c.ValidUntil IS NULL OR c.ValidUntil >= CAST(GETDATE() AS date))), crew AS (SELECT s.Vsl_StaffID, s.VesselID, s.UserID, s.UserName, s.UserRank FROM dbo.Vsl_Staff s WHERE ISNULL(s.IsDisabled, 0) = 0 AND (s.LeavingDate IS NULL OR s.LeavingDate > GETDATE()))
	SELECT ves.VesselID, ves.VslName AS VesselName, 'Manual' AS ItemType, man.DM_ManualID AS ItemID, man.ManualNo AS Number, man.ManualName AS Title, man.Version, s.UserRank AS Rank, s.UserID, s.UserName, CAST(NULL AS varchar(25)) AS Dept, man.ReleasedOn, DATEADD(day, man.AckDueDays, man.ReleasedOn) AS DueOn, man.AckDueDays FROM (SELECT DISTINCT ves.VesselID, t.DM_ManualID, t.UserRank FROM dbo.DM_Manual_ToAck_Vsl t JOIN vessels ves ON t.VesselID IN (ves.VesselID, -1) WHERE ISNULL(t.IsActive, 1) = 1) r JOIN vessels ves ON ves.VesselID = r.VesselID JOIN man ON man.DM_ManualID = r.DM_ManualID JOIN crew s ON s.VesselID = r.VesselID AND s.UserRank = r.UserRank WHERE NOT EXISTS (SELECT 1 FROM dbo.DM_Manual_UserAck a WHERE a.DM_ManualVersionID = man.DM_ManualVersionID AND a.UserID = s.UserID)
	UNION ALL
	SELECT ves.VesselID, ves.VslName, cir.ItemType, cir.CIR_MasterID, cir.CIR_Number, cir.Title, NULL, s.UserRank, s.UserID, s.UserName, CAST(NULL AS varchar(25)), cir.ReleasedOn, DATEADD(day, cir.AckDueDays, cir.ReleasedOn), cir.AckDueDays FROM (SELECT DISTINCT ves.VesselID, t.CIR_MasterID, t.UserRank FROM dbo.CIR_ToAck_Vsl t JOIN vessels ves ON t.VesselID IN (ves.VesselID, -1) WHERE ISNULL(t.IsActive, 1) = 1) r JOIN vessels ves ON ves.VesselID = r.VesselID JOIN cir ON cir.CIR_MasterID = r.CIR_MasterID JOIN crew s ON s.VesselID = r.VesselID AND s.UserRank = r.UserRank WHERE NOT EXISTS (SELECT 1 FROM dbo.CIR_UserAck a WHERE a.CIR_MasterID = cir.CIR_MasterID AND a.Fleet_CrewID = s.Vsl_StaffID);
END;
GO
